      "content": "import { expect, test } from 'bun:test';
import { DomainError, type UseCaseContext } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { CreateTask } from '../application/create-task';
import { TaskCreated } from '../domain/task.events';
import type { Task } from '../domain/task';
import type { TaskRepository } from '../domain/task.repository';

test(covers(['usecase:create_task', 'criterion:0001/persistencia-criacao'], 'create_task salva pending, publica TaskCreated e rejeita id duplicado'), async () => {
  const storage = new Map<string, Task>();
  const saved: Task[] = [];
  const published: unknown[][] = [];
  const repo: TaskRepository = { findById: async (id) => storage.get(id) ?? null, save: async (task) => { saved.push(task); storage.set(task.id, task); } };
  const ctx: UseCaseContext = { correlationId: 'corr-1', causationId: 'cause-1', publish: async (events) => { published.push([...events]); } };
  const useCase = new CreateTask(repo);

  const output = await useCase.execute({ task_id: 't1', title: '  pagar contas  ' }, ctx);
  expect(output).toEqual({ task_id: 't1', title: 'pagar contas', status: 'pending' });
  expect(saved).toHaveLength(1);
  expect(saved[0]?.id).toBe('t1');
  expect(saved[0]?.status).toBe('pending');
  expect(published).toHaveLength(1);
  expect(published[0]).toHaveLength(1);
  expect(published[0]?.[0]).toBeInstanceOf(TaskCreated);
  expect((published[0]?.[0] as TaskCreated).payload).toEqual({ taskId: 't1', title: 'pagar contas' });

  const act = () => useCase.execute({ task_id: 't1', title: 'outra tarefa' }, ctx);
  await expect(act()).rejects.toBeInstanceOf(DomainError);
  try {
    await act();
  } catch (error) {
    expect(error).toBeInstanceOf(DomainError);
    expect((error as DomainError).code).toBe('TASK_ALREADY_EXISTS');
    return;
  }
  throw new Error('expected create_task to throw');
});
